contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address token, address[] memory tos, uint[] memory vals) public {
        require(tos.length == vals.length);

        bool reverted;
        if (tos.length == 0) {
            // empty recipient list must revert
            try c.transfer(from, token, tos, vals) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        } else {
            // non-empty list: call succeeds and returns true, even if token transfers fail
            bool ok = c.transfer(from, token, tos, vals);
            assert(ok == true);
        }
    }

    receive() external payable {}
}

