contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address token, address[] memory tos, uint[] memory vals) public payable {
        require(tos.length >= 1);
        require(vals.length == tos.length);
        bool ok;
        bool reverted;
        try c.transfer(from, token, tos, vals) returns (bool r) {
